body:
This is really deeply nested with { { { { } } } } -- can you flatten it? Try inverting some of the conditions to exit early for example or assign the arrays after the if conditions.

One example from codex:
```rust
pub(crate) fn normalize_tool_call_arguments(messages_json: &mut serde_json::Value) {
    let Some(messages) = messages_json.as_array_mut() else {
        return;
    };

    for message in messages {
        let Some(tool_calls) = message
            .get_mut("tool_calls")
            .and_then(serde_json::Value::as_array_mut)
        else {
            continue;
        };

        for tool_call in tool_calls {
            let Some(arguments) = tool_call.pointer_mut("/function/arguments") else {
                continue;
            };

            let Some(arguments_str) = arguments.as_str() else {
                continue;
            };

            let Ok(parsed) = serde_json::from_str(arguments_str) else {
                continue;
            };

            *arguments = parsed;
        }
    }
}
